// SetArrayElement updates one element of a slice/array-valued target column.
// It is the Go-native fluent equivalent of an on-trigger assignment such as
// target.items[index] = value. The index and value remain analyzable
// expressions instead of being embedded in a string rule.
func SetArrayElement(column string, index, expression Expr) TableAssignment {
	return internalengine.SetArrayElement(column, index, expression)
}

func SetColumn(column string, expression Expr) TableAssignment {
	return internalengine.SetColumn(column, expression)
}

// SetMapEntry updates one keyed entry of a map-valued target column. It is
// the Go-native fluent equivalent of an update assignment such as
// target.props('abc') = value. The key and value remain analyzable
// expressions instead of being embedded in a string rule.
func SetMapEntry(column string, key, expression Expr) TableAssignment {
	return internalengine.SetMapEntry(column, key, expression)
}

// SetOfValues returns distinct non-null values in first-seen order.
