// Signum is the Go-native equivalent of Java Math.signum for double-valued
// expressions. NaN and negative zero are preserved, while finite values are
// normalized to -1, 0, or 1.
func Signum(value Expression[float64]) Expression[float64] {
	return internalengine.Signum(value)
}

// SimpleCaseBuilder builds a CASE expression that evaluates one value and
// compares it with each WHEN value in declaration order. Match expressions
// intentionally use Expr instead of a second generic parameter: this keeps
// numeric and nullable comparison useful across Go's distinct numeric types
// while the result type remains statically checked.
type SimpleCaseBuilder[T any] = internalengine.SimpleCaseBuilder[T]

// Sink is the chain endpoint for asynchronous integration adapters. The
// default Engine path still invokes it synchronously for Esper-like ordering.
type Sink = internalengine.Sink

type SinkFunc = internalengine.SinkFunc

// SomeOf is the SQL/Esper synonym for AnyOf.
func SomeOf(value Expr, comparison QuantifierComparison, candidates ...Expr) Expression[bool] {
	return internalengine.SomeOf(value, comparison, candidates...)
}

type SortKey = internalengine.SortKey

func SortWindow(size int, keys ...SortKey) SortedWindowSpec {
	return internalengine.SortWindow(size, keys...)
}

// SortedAccessBy creates a sorted access aggregate over value and key. The
// key is ordered ascending and duplicate keys form insertion-ordered buckets.
func SortedAccessBy[V any, K Ordered](value Expression[V], key Expression[K]) SortedAccessExpression[V, K] {
	return internalengine.SortedAccessBy[V, K](value, key)
}

// SortedAccessByMulti creates a sorted access aggregate with two ordered key
// expressions. Keys compare lexicographically, matching Esper's
// HashableMultiKey/TreeMap behavior while keeping the rule fully typed and
// analyzable in Go.
func SortedAccessByMulti[V any, A Ordered, B Ordered](value Expression[V], first Expression[A], second Expression[B]) SortedAccessExpression[V, SortedMultiKey] {
	return internalengine.SortedAccessByMulti[V, A, B](value, first, second)
}

// SortedAccessEntry is one key bucket in a SortedAccessValue. Values sharing
// a key retain their input insertion order.
type SortedAccessEntry[K Ordered, V any] = internalengine.SortedAccessEntry[K, V]

// SortedAccessExpression is the chainable Go representation of Esper's
// sorted(...) access aggregation. Its methods return analyzable aggregate
// expressions, so access operations can be selected, filtered by HAVING, or
// composed with other result expressions without EPL strings.
type SortedAccessExpression[V any, K Ordered] = internalengine.SortedAccessExpression[V, K]

// SortedAccessIterator is a detached, read-only iterator over key buckets.
// Next returns copies, so advancing or mutating a returned bucket cannot
// change the aggregate snapshot held by a table or statement.
type SortedAccessIterator[K Ordered, V any] = internalengine.SortedAccessIterator[K, V]

// SortedAccessValue is the immutable, navigable result of SortedAccessBy.
// It intentionally exposes copies so callers cannot mutate aggregate state
// held by a deployed statement.
type SortedAccessValue[K Ordered, V any] = internalengine.SortedAccessValue[K, V]

// SortedEvents returns current group events ordered by one or more analyzable
// sort keys. It is the Go counterpart of sorted(*) with multi-criteria order.
func SortedEvents(keys ...SortKey) AggregateExpression[[]Event] {
	return internalengine.SortedEvents(keys...)
}

// SortedMultiKey is an immutable lexicographic key for multi-criteria sorted
// access aggregates. Each component keeps its Value state so a caller can
// distinguish a present component from Null/Missing when inspecting a key;
// sorted access itself only indexes rows whose complete key is present.
type SortedMultiKey = internalengine.SortedMultiKey

// SortedValues returns non-null values ordered by their natural Go ordering.
func SortedValues[T Ordered](expression Expression[T], descending bool) AggregateExpression[[]T] {
	return internalengine.SortedValues[T](expression, descending)
}

type SortedWindowSpec = internalengine.SortedWindowSpec

// Split returns the ordered string elements produced by splitting value on
// separator. It is the Go-style, analyzable counterpart of a string split
// function used as a contained-event source expression; the resulting slice
// can be passed directly to UnnestValues.
func Split(value, separator Expression[string]) Expression[[]string] {
	return internalengine.Split(value, separator)
}

// SplitFrom starts a branch-local source traversal. The source must resolve
// to the same root event type as the OnEvent trigger and may add stateless
// Filter and Unnest operators. Branches are evaluated in declaration order.
func SplitFrom[T any](source Stream[T]) SplitStreamBranchBuilder {
	return internalengine.SplitFrom[T](source)
}

// SplitInto creates an unconditional split branch.
func SplitInto(target string, selections ...Selection) SplitStreamBranch {
	return internalengine.SplitInto(target, selections...)
}

// SplitIntoWhen creates a conditional split branch.
func SplitIntoWhen(condition Expr, target string, selections ...Selection) SplitStreamBranch {
	return internalengine.SplitIntoWhen(condition, target, selections...)
}

// SplitStreamBranch is one ordered branch of an on-event split. A nil
// Condition is unconditional and an empty Selections slice forwards the
// complete source event. The target event type remains explicit because Go
// does not synthesize public schemas from EPL text.
type SplitStreamBranch = internalengine.SplitStreamBranch

// SplitStreamBranchBuilder binds one split branch to a fluent source derived
// from the trigger stream. It is the Go counterpart of an EPL split-stream
// branch that carries its own contained-event from-clause.
type SplitStreamBranchBuilder = internalengine.SplitStreamBranchBuilder

func StartsWith(value, prefix Expression[string]) Expression[bool] {
	return internalengine.StartsWith(value, prefix)
}

type Statement = internalengine.Statement

// StatementAnnotation is one immutable custom annotation instance.
type StatementAnnotation = internalengine.StatementAnnotation

// StatementAnnotationDefinition is an immutable custom annotation contract.
type StatementAnnotationDefinition = internalengine.StatementAnnotationDefinition

// StatementAudit enables typed runtime audit categories for the statement.
// With no arguments it enables every category, matching Esper's bare @Audit
// annotation without exposing the comma-separated EPL representation.
func StatementAudit(categories ...AuditCategory) QueryOption {
	return internalengine.StatementAudit(categories...)
}

// StatementCompileContext describes one typed statement before Build validates
// and canonicalizes it. TypedDescription replaces Java's raw EPL supplier;
// Query and Metadata expose the analyzable fluent source without parsing text.
type StatementCompileContext = internalengine.StatementCompileContext

// StatementContains searches the statement name, deployment id and canonical
// fluent Plan. This replaces Esper's EPL-text contains traversal while keeping
// selection independent of a text compiler.
func StatementContains(text string) StatementPredicate {
	return internalengine.StatementContains(text)
}

// StatementDeploymentIDContains selects statements whose stable deployment
// id contains text. It is the typed counterpart to management expressions over
