type StatementParameterResolver = internalengine.StatementParameterResolver

// StatementPredicate is a typed statement-management filter. Predicates run
// against a detached ordered snapshot, so they may inspect Plan metadata
// without holding the Engine transaction lock.
type StatementPredicate = internalengine.StatementPredicate

// StatementPriority orders ordinary continuous statements for one dispatch
// cycle. Higher values run first; equal values keep deployment order except
// that StatementDrop entries run before non-drop entries.
//
// Update-istream preprocessing has its own ascending priority contract and
// therefore continues to use UpdatePriority instead.
func StatementPriority(priority int) QueryOption {
	return internalengine.StatementPriority(priority)
}

// StatementSchedule identifies the nearest pending engine-clock callback for
// one deployed statement. At is expressed in the same time domain as Now and
// AdvanceTime; DeploymentID and StatementName form a stable lookup pair.
type StatementSchedule = internalengine.StatementSchedule

const StatementStarted = internalengine.StatementStarted

type StatementState = internalengine.StatementState

const StatementStopped = internalengine.StatementStopped

