func WithStartTime(start time.Time) EngineOption {
	return internalengine.WithStartTime(start)
}

// WithStatementAnnotation attaches one validated application-defined
// annotation instance.
func WithStatementAnnotation(annotation StatementAnnotation) QueryOption {
	return internalengine.WithStatementAnnotation(annotation)
}

// WithStatementHints attaches already-validated built-in hints. Semantic
// builder controls such as RowRecogQuery.IterateOnly remain explicit in their
// respective fluent chain; this option exposes the corresponding metadata.
func WithStatementHints(hints ...StatementHint) QueryOption {
	return internalengine.WithStatementHints(hints...)
}

// WithStatementMetrics enables statement-level metrics. Non-positive
// intervals disable scheduling while retaining accounting and allowing the
// interval to be enabled later through SetStatementMetricGroupInterval.
func WithStatementMetrics(defaultInterval time.Duration, groups ...StatementMetricGroupConfig) EngineOption {
	return internalengine.WithStatementMetrics(defaultInterval, groups...)
}

// WithStatementNameResolver resolves the compile-time statement name from a
// typed fluent query context.
func WithStatementNameResolver(resolver StatementNameResolver) CompileOption {
	return internalengine.WithStatementNameResolver(resolver)
}

// WithStatementUserObject attaches an opaque caller-owned value to the
// statement metadata exposed by CurrentEvaluationContext. It is not evaluated
// as part of the rule and does not enter Plan canonical identity.
func WithStatementUserObject(value any) QueryOption {
	return internalengine.WithStatementUserObject(value)
}

// WithStatementUserObjectResolver resolves application-owned compile-time
// metadata after any statement-name resolver has run.
func WithStatementUserObjectResolver(resolver StatementUserObjectResolver) CompileOption {
	return internalengine.WithStatementUserObjectResolver(resolver)
}

// WithTableColumnNestedSchema associates a composite column with its nested
// event schema. The same schema is used for a scalar composite value and for
// every element of an array/slice composite value.
func WithTableColumnNestedSchema(nested Schema) TableColumnOption {
	return internalengine.WithTableColumnNestedSchema(nested)
}

// WithTimerWorkers enables AdvanceTimeAsync.
func WithTimerWorkers(workers, queueCapacity int) EngineOption {
	return internalengine.WithTimerWorkers(workers, queueCapacity)
}

// WithTypedPropertyGetter is the type-safe convenience form of
// WithPropertyGetter. A returned Go nil is represented as Null.
func WithTypedPropertyGetter[T any](name string, getter func(any) (T, error)) SchemaOption {
	return internalengine.WithTypedPropertyGetter[T](name, getter)
}

// WithTypedPropertySetter is the type-safe convenience form of
// WithPropertySetter.
func WithTypedPropertySetter[T any](name string, setter func(any, T) error) SchemaOption {
	return internalengine.WithTypedPropertySetter[T](name, setter)
}

func WithXMLDefaultAsAttribute(enabled bool) XMLRenderOption {
	return internalengine.WithXMLDefaultAsAttribute(enabled)
}

func WithXMLIndent(indent string) XMLRenderOption {
	return internalengine.WithXMLIndent(indent)
}

func WithXMLMaxDepth(depth int) XMLRenderOption {
	return internalengine.WithXMLMaxDepth(depth)
}

func WithXMLParseMaxDepth(depth int) XMLParseOption {
	return internalengine.WithXMLParseMaxDepth(depth)
}

func WithXMLTitle(title string) XMLRenderOption {
	return internalengine.WithXMLTitle(title)
}

func WrapError(code ErrorCode, path string, cause error) error {
	return internalengine.WrapError(code, path, cause)
}

// XMLParseConfig controls the secure, tree-backed XML event parser.
type XMLParseConfig = internalengine.XMLParseConfig

// XMLParseOption changes XML decoding behavior.
type XMLParseOption = internalengine.XMLParseOption

// XMLRenderConfig controls XML output. XML uses repeated element names for
// array values, matching Esper's event renderer contract.
type XMLRenderConfig = internalengine.XMLRenderConfig

// XMLRenderOption changes XML rendering behavior.
type XMLRenderOption = internalengine.XMLRenderOption

func Year(value Expression[time.Time]) Expression[int64] {
	return internalengine.Year(value)
}
